import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as WorkOSUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Maps a WorkOS user onto our own User shape and upserts it into the local
// store, so people who sign up/in through AuthKit show up alongside the
// existing seed users instead of needing a separate lookup path.
function syncUser(workosUser: WorkOSUser): User {
  const existing = users.find((u) => u.id === workosUser.id);
  const synced: User = {
    id: workosUser.id,
    email: workosUser.email,
    name: workosUser.name ?? workosUser.email,
    createdAt: existing?.createdAt ?? workosUser.createdAt,
  };

  if (existing) {
    Object.assign(existing, synced);
  } else {
    users.push(synced);
  }

  return synced;
}

// Backed by the real AuthKit session now — returns undefined for
// signed-out visitors instead of always picking the first seed user.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  return user ? syncUser(user) : undefined;
}

