import { withAuth } from "@workos-inc/authkit-nextjs";
import { getCurrentUser, listUsers } from "@/lib/users";

export default async function DashboardPage() {
  // The proxy already blocks signed-out visitors from reaching this route;
  // ensureSignedIn here is a second guard in case the page is ever rendered
  // some other way.
  await withAuth({ ensureSignedIn: true });

  const me = await getCurrentUser();
  const all = await listUsers();

  return (
    <main className="mx-auto max-w-2xl p-8">
      <div className="flex items-start justify-between">
        <h1 className="text-2xl font-semibold">Dashboard</h1>
        <form action="/sign-out" method="post">
          <button
            type="submit"
            className="text-sm underline underline-offset-4 opacity-70 hover:opacity-100"
          >
            Sign out
          </button>
        </form>
      </div>
      <p className="mt-2 text-sm opacity-70">
        Signed in as {me?.name ?? "nobody"} ({me?.email ?? "—"})
      </p>

      <h2 className="mt-8 text-lg font-medium">Team</h2>
      <ul className="mt-2 space-y-1">
        {all.map((u) => (
          <li key={u.id} className="text-sm">
            {u.name} — {u.email} — joined {u.createdAt}
          </li>
        ))}
      </ul>
    </main>
  );
}

